import { Checkbox } from '@absoluteui/components/checkbox';

const host = document.createElement('div');
document.body.append(host);
const terms = Checkbox.create(host, { label: 'I accept the terms and conditions', name: 'terms', value: 'accepted', required: true });
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(terms.validity.valid);
});

import { Checkbox } from '@absoluteui/components/checkbox';

const host = document.createElement('div');
document.body.append(host);
const all = Checkbox.create(host, { label: 'Select all files', indeterminate: true });
function syncSelectAll(selected: number, total: number): void {
  all.setChecked(selected === total, selected > 0 && selected < total);
}
syncSelectAll(3, 5);
